questionvariables.text:
/* Part (a): det(A+B) vs det A + det B  (NOT equal) */
a_sum_ta    : matrix([a+p,b+q],[c+r,d+s]);
a_detsum_ta : (a+p)*(d+s)-(b+q)*(c+r);
a_sumdet_ta : (a*d-b*c)+(p*s-q*r);
a_eq_ta     : [[true,false,"Yes: equal for all such matrices"],[false,true,"No: not equal in general"]];

/* Part (b): det(kval*A) vs kval^2 det A  (equal). kval randomised;
   2..6 avoids the degenerate scalars 0 and 1. */
kval : rand([2,3,4,5,6]);
b_scal_ta    : matrix([kval*a,kval*b],[kval*c,kval*d]);
b_detscal_ta : (kval*a)*(kval*d)-(kval*b)*(kval*c);
b_rhs_ta     : kval^2*(a*d-b*c);
b_eq_ta      : [[true,true,"Yes: equal for all such matrices"],[false,false,"No: not equal in general"]];

/* Part (c): det(A^2) vs 2 det A  (NOT equal) */
c_sq_ta    : matrix([a^2+b*c, a*b+b*d],[a*c+c*d, b*c+d^2]);
c_detsq_ta : (a*d-b*c)^2;
c_rhs_ta   : 2*(a*d-b*c);
c_eq_ta    : [[true,false,"Yes: equal for all such matrices"],[false,true,"No: not equal in general"]];

/* Follow-up boxes on the false parts (a),(c), revealed on "No: not equal in general".
   Marking is by property, so these are only sample instances. */
a_ce1_ta : matrix([1,0],[0,1]);
a_ce2_ta : matrix([2,0],[0,2]);
a_sp_ta  : [[true,true,"Yes, for some special choices"],[false,false,"No, the two sides are never equal"]];
a_sp1_ta : matrix([1,0],[0,1]);
a_sp2_ta : matrix([0,0],[0,0]);
/* (b) trap: the claim is true, so no counterexample exists; dummy model answer. */
bce1_ta  : matrix([1,0],[0,1]);
c_ce1_ta : matrix([1,0],[0,1]);
c_sp_ta  : [[true,true,"Yes, for some special choices"],[false,false,"No, the two sides are never equal"]];
c_sp1_ta : matrix([2,0],[0,1]);

feedbackvariables.text:
filled_ace : matrixp(ace1) and matrixp(ace2);
num_ace : if filled_ace then every(numberp, append(flatten(args(ace1)), flatten(args(ace2)))) else false;
gap_ace : if num_ace then determinant(ace1+ace2) - (determinant(ace1)+determinant(ace2)) else 1;
/* guarded copies for display; zero matrices when empty/non-numeric */
mA_ace : if num_ace then ace1 else matrix([0,0],[0,0]);
mB_ace : if num_ace then ace2 else matrix([0,0],[0,0]);
sum_ace : mA_ace + mB_ace;
s11 : sum_ace[1,1]; s12 : sum_ace[1,2]; s21 : sum_ace[2,1]; s22 : sum_ace[2,2];
p11 : mA_ace[1,1]; p12 : mA_ace[1,2]; p21 : mA_ace[2,1]; p22 : mA_ace[2,2];
q11 : mB_ace[1,1]; q12 : mB_ace[1,2]; q21 : mB_ace[2,1]; q22 : mB_ace[2,2];
lhs_ace : determinant(sum_ace);
d1_ace  : determinant(mA_ace);
d2_ace  : determinant(mB_ace);
rhs_ace : d1_ace + d2_ace;

filled_asp : matrixp(asp1) and matrixp(asp2);
num_asp : if filled_asp then every(numberp, append(flatten(args(asp1)), flatten(args(asp2)))) else false;
gap_asp : if num_asp then determinant(asp1+asp2) - (determinant(asp1)+determinant(asp2)) else 1;
/* guarded copies for display; zero matrices when empty/non-numeric */
mA_asp : if num_asp then asp1 else matrix([0,0],[0,0]);
mB_asp : if num_asp then asp2 else matrix([0,0],[0,0]);
sum_asp : mA_asp + mB_asp;
t11 : sum_asp[1,1]; t12 : sum_asp[1,2]; t21 : sum_asp[2,1]; t22 : sum_asp[2,2];
u11 : mA_asp[1,1]; u12 : mA_asp[1,2]; u21 : mA_asp[2,1]; u22 : mA_asp[2,2];
v11 : mB_asp[1,1]; v12 : mB_asp[1,2]; v21 : mB_asp[2,1]; v22 : mB_asp[2,2];
lhs_asp : determinant(sum_asp);
d1_asp  : determinant(mA_asp);
d2_asp  : determinant(mB_asp);
rhs_asp : d1_asp + d2_asp;

filled_bce : matrixp(bce1);
num_bce : if filled_bce then every(numberp, flatten(args(bce1))) else false;
/* guarded copies for display; zero matrices when empty/non-numeric */
mA_bce : if num_bce then bce1 else matrix([0,0],[0,0]);
mk_bce : kval*mA_bce;
m11 : mk_bce[1,1]; m12 : mk_bce[1,2]; m21 : mk_bce[2,1]; m22 : mk_bce[2,2];
n11 : mA_bce[1,1]; n12 : mA_bce[1,2]; n21 : mA_bce[2,1]; n22 : mA_bce[2,2];
lhs_bce : determinant(mk_bce);
d_bce   : determinant(mA_bce);
rhs_bce : kval^2*d_bce;
gap_bce : if num_bce then lhs_bce - rhs_bce else 1;

filled_cce : matrixp(cce1);
num_cce : if filled_cce then every(numberp, flatten(args(cce1))) else false;
gap_cce : if num_cce then determinant(cce1^^2) - 2*determinant(cce1) else 1;
/* guarded copies for display; zero matrices when empty/non-numeric */
mA_cce : if num_cce then cce1 else matrix([0,0],[0,0]);
sq_cce : mA_cce^^2;
w11 : sq_cce[1,1]; w12 : sq_cce[1,2]; w21 : sq_cce[2,1]; w22 : sq_cce[2,2];
r11 : mA_cce[1,1]; r12 : mA_cce[1,2]; r21 : mA_cce[2,1]; r22 : mA_cce[2,2];
lhs_cce : determinant(sq_cce);
d_cce   : determinant(mA_cce);
rhs_cce : 2*d_cce;

filled_csp : matrixp(csp1);
num_csp : if filled_csp then every(numberp, flatten(args(csp1))) else false;
gap_csp : if num_csp then determinant(csp1^^2) - 2*determinant(csp1) else 1;
/* guarded copies for display; zero matrices when empty/non-numeric */
mA_csp : if num_csp then csp1 else matrix([0,0],[0,0]);
sq_csp : mA_csp^^2;
y11 : sq_csp[1,1]; y12 : sq_csp[1,2]; y21 : sq_csp[2,1]; y22 : sq_csp[2,2];
z11 : mA_csp[1,1]; z12 : mA_csp[1,2]; z21 : mA_csp[2,1]; z22 : mA_csp[2,2];
lhs_csp : determinant(sq_csp);
d_csp   : determinant(mA_csp);
rhs_csp : 2*d_csp;
